function s(t){const[n=NaN,e=NaN,a=NaN]=t.split("-").map(Number);return[n,e,a]}function o(t){const[n,e,a]=s(t);return Date.UTC(n,e-1,a)}function u(t){return new Date(t).toISOString().slice(0,10)}function D(t){return/^\d{4}-\d{2}-\d{2}$/.test(t)&&u(o(t))===t}function d(t,n){return u(o(t)+n*864e5)}function y(t,n){const[e,a,c]=s(t),r=new Date(Date.UTC(e,a-1+n,1)),i=new Date(Date.UTC(r.getUTCFullYear(),r.getUTCMonth()+1,0)).getUTCDate();return r.setUTCDate(Math.min(c,i)),u(r.getTime())}function T(t,n){return Math.round((o(n)-o(t))/864e5)}function h(t,n){const[e,a,c]=s(t),[r,i,m]=s(n);return(r-e)*12+(i-a)-(m<c?1:0)}const U=(t,n)=>t>n?t:n,f=new Intl.DateTimeFormat("th-TH",{timeZone:"UTC",day:"numeric",month:"long",year:"numeric"});function C(t){return f.format(new Date(o(t)))}export{y as a,d as b,T as d,C as f,D as i,U as l,h as m};
